import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { spawnSync } from "node:child_process";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";

const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const playwrightVersion = require("playwright/package.json").version;

const SOURCE = fileURLToPath(import.meta.url);
const ASSETS = path.dirname(SOURCE);
const VISUAL = path.dirname(ASSETS);
const SUB = path.dirname(VISUAL);
const FIGURES = path.join(SUB, "assets", "figures");
const MEDIA = path.join(SUB, "assets", "media");
const DRAWINGS = path.join(SUB, "drawings");
const REPORT = path.join(SUB, "report");
const FREEZE_PATH = path.join(ASSETS, "phase4-source-freeze.json");
const AUDIT_PATH = path.join(ASSETS, "phase4-presentation-audit.json");
const FIGURE_REGISTRY_PATH = path.join(ASSETS, "phase4-figure-registry.json");
const LAYOUT_PATH = path.join(ASSETS, "phase4-layout-contract.json");
const CONTRACT_PATH = path.join(ASSETS, "phase4-generation-contract.json");
const PROTOCOLS_PATH = path.join(ASSETS, "phase3-protocol-contracts.json");
const RED_TEAM_PATH = path.join(ASSETS, "phase3-red-team.json");
const R3_CONTEXT_PATH = path.join(ASSETS, "r3-site-context.json");
const NEGATIVE_A3_HEADER_OVERLAP = process.argv.includes("--negative-a3-header-overlap");
const NEGATIVE_OUTLINE_GLUE = process.argv.includes("--negative-outline-glue");
const PDF_HEADER_ASSERTIONS = {};
const PDF_OUTLINE_ASSERTIONS = {};
const EXPECTED_ENGLISH_OUTLINE_COUNTS = {
  "a3-booklet.en.pdf": 29,
  "a0-boards.en.pdf": 22,
};
const FORBIDDEN_ENGLISH_OUTLINE_GLUE = [
  "ZeroOverlaps",
  "ThreeDetailed",
  "OneGrammar",
  "HumanTakeover",
  "Thermal-SafetyBench",
  "MatchingClinic",
  "TrialRoom",
  "+Components",
];

const OUTPUTS = [
  "assets/media/cover.webp",
  "drawings/a3-booklet.pdf",
  "drawings/a3-booklet.en.pdf",
  "drawings/a0-boards.pdf",
  "drawings/a0-boards.en.pdf",
  "report/proposal.html",
  "report/proposal.en.html",
  "visual/index.html",
  "visual/index.en.html",
  "visual/assets/font-subset.css",
  "visual/assets/visual.css",
  "visual/assets/visual.js",
];

const COLORS = {
  bg: "#f3f0e7",
  paper: "#fffdf7",
  ink: "#162126",
  muted: "#596260",
  dark: "#173b42",
  teal: "#2d7980",
  orange: "#b53a21",
  blue: "#2a5f93",
  gold: "#b8893d",
  green: "#577a5c",
  purple: "#665788",
  line: "#a9a496",
  pale: "#e7e2d6",
};

function readText(target) {
  return fs.readFileSync(target, "utf8");
}

function readJson(target) {
  return JSON.parse(readText(target));
}

function writeText(target, value) {
  fs.mkdirSync(path.dirname(target), { recursive: true });
  const normalized = value.replace(/\r\n/g, "\n").replace(/\n{3,}/g, "\n\n");
  fs.writeFileSync(target, normalized, "utf8");
}

function writeTextAtomic(target, value) {
  const temporary = `${target}.${process.pid}.tmp`;
  writeText(temporary, value);
  fs.renameSync(temporary, target);
}

function sha256(target) {
  return crypto.createHash("sha256").update(fs.readFileSync(target)).digest("hex");
}

function normalizeOutlineWhitespace(value) {
  return String(value).replace(/\s+/g, " ").trim();
}

function esc(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function mime(target) {
  const ext = path.extname(target).toLowerCase();
  return ext === ".webp" ? "image/webp" : ext === ".jpg" || ext === ".jpeg" ? "image/jpeg" : "image/png";
}

function dataUrl(target) {
  return `data:${mime(target)};base64,${fs.readFileSync(target).toString("base64")}`;
}

function stripMarked(value, label) {
  const pattern = new RegExp(`<!-- ${label}_START -->[\\s\\S]*?<!-- ${label}_END -->`, "g");
  return value.replace(pattern, "");
}

function assertFrozen() {
  const freeze = readJson(FREEZE_PATH);
  const failures = [];
  const protectedFiles = freeze.protected_phase2_inputs.files;
  for (const [relative, record] of Object.entries(protectedFiles)) {
    const target = path.join(SUB, relative);
    const actual = fs.existsSync(target) ? sha256(target) : "missing";
    if (actual !== record.expected_sha256) failures.push(`${relative}: ${actual}`);
  }
  for (const [relative, expected] of Object.entries(freeze.authoritative_semantic_inputs_sha256)) {
    const target = path.join(SUB, relative);
    const actual = fs.existsSync(target) ? sha256(target) : "missing";
    if (actual !== expected) failures.push(`${relative}: ${actual}`);
  }
  const repo = path.resolve(SUB, "..", "..", "..");
  for (const [relative, expected] of Object.entries(freeze.repository_rule_inputs_sha256)) {
    const target = path.join(repo, relative);
    const actual = fs.existsSync(target) ? sha256(target) : "missing";
    if (actual !== expected) failures.push(`${relative}: ${actual}`);
  }
  if (failures.length) throw new Error(`Frozen input drift:\n${failures.join("\n")}`);
  return freeze;
}

function figureById(registry, id) {
  const found = registry.figures.find((item) => item.id === id);
  if (!found) throw new Error(`Missing figure registry entry ${id}`);
  return found;
}

function languageValue(item, root, lang) {
  return item[`${root}_${lang}`];
}

function legendHtml(lang, compact = false) {
  const items = lang === "zh"
    ? [
        ["known", "已知 / 可复算"],
        ["provisional", "临时约束"],
        ["unknown", "未知 / 待补"],
        ["design", "设计目标"],
        ["takeover", "H · 人工接管"],
        ["stop", "X · 停止 / 撤场"],
      ]
    : [
        ["known", "Known / recomputable"],
        ["provisional", "Provisional constraint"],
        ["unknown", "Unknown / pending"],
        ["design", "Design target"],
        ["takeover", "H · Human Takeover"],
        ["stop", "X · Stop / remove"],
      ];
  return `<ul class="state-legend${compact ? " compact" : ""}" aria-label="${lang === "zh" ? "状态、置信度与人工接管图例" : "Status, confidence, and human-takeover legend"}">${items
    .map(([key, label]) => `<li><span class="state-symbol ${key}" aria-hidden="true"></span><span>${esc(label)}</span></li>`)
    .join("")}</ul>`;
}

function reportPhase4Css() {
  return `
<style id="phase4-report-style">
@import url('../visual/assets/font-subset.css');
html{scroll-behavior:smooth}body{font-family:'JZ Noto Sans SC',sans-serif;font-synthesis:none}b,strong,h1,h2,h3,h4,.document-title,.phase4-guide nav a,.figure-details summary{font-weight:700!important}
.phase4-skip{position:fixed;left:1rem;top:.5rem;z-index:50;transform:translateY(-180%);padding:.7rem 1rem;background:#162126;color:white;border-radius:.35rem;font-weight:800}.phase4-skip:focus{transform:none}.phase4-skip:focus-visible{outline:4px solid #b53a21;outline-offset:3px}
.phase4-guide{margin:0 0 2rem;padding:1.25rem 1.35rem;border:2px solid #173b42;border-left:8px solid #b53a21;background:#fffdf7}.phase4-guide h2{margin:0 0 .65rem;padding:0;border:0;font-size:1.25rem}.phase4-guide nav{display:flex;gap:.55rem;flex-wrap:wrap}.phase4-guide nav a{display:inline-block;padding:.48rem .7rem;border:2px solid #173b42;color:#173b42;background:white;font:inherit;font-weight:800;text-decoration:none;cursor:pointer}.phase4-guide nav a:focus-visible,.figure-details summary:focus-visible,.figure-details-viewport:focus-visible,.proposal-table:focus-visible{outline:4px solid #b53a21;outline-offset:3px}.phase4-guide p{margin:.8rem 0}.phase4-guide .r3-site-chain{padding:.8rem 1rem;border:3px solid #b53a21;background:#fff5e8}.document-title{font-size:1.4rem;font-weight:800;line-height:1.3;margin:1.4rem 0 .6rem}.proposal-figure[id]{scroll-margin-top:1rem}.figure-details{margin:0}.figure-details summary{display:block;position:relative;cursor:pointer}.figure-details summary::-webkit-details-marker{display:none}.figure-details summary img{display:block;width:100%}.figure-details summary span{display:block;padding:.55rem .75rem;background:#173b42;color:white}.figure-details[open] summary span:before{content:'✓ '}.figure-details-panel{margin-top:.7rem;border:3px solid #173b42;background:#f7f2e8}.figure-details-viewport{height:min(72vh,900px);overflow:auto;overscroll-behavior:contain;background:#e8e3d8}.figure-details-viewport img{display:block;width:200%;max-width:none;height:auto}.figure-details-panel p{margin:0;padding:.65rem .85rem}.proposal-table[tabindex="0"]{scrollbar-gutter:stable;border-bottom:3px solid #173b42}.proposal-table[tabindex="0"]:before{content:'↔';position:sticky;left:0;display:inline-block;padding:.15rem .4rem;background:#173b42;color:white;font-weight:900}.phase4-boundaries{margin-top:2.5rem;padding:1.2rem 1.4rem;border-top:6px solid #b53a21;background:#f7f2e8}.phase4-boundaries h2{margin-top:0;padding-top:0;border-top:0}.state-legend{display:flex;flex-wrap:wrap;gap:.55rem 1rem;margin:.9rem 0;padding:0;list-style:none}.state-legend li{display:flex;align-items:center;gap:.4rem;font-weight:700}.state-symbol{display:inline-grid;width:1.2rem;height:1.2rem;place-items:center;border:3px solid currentColor}.state-symbol.known{color:#2d7980;border-radius:50%;background:#2d7980}.state-symbol.provisional{color:#b8893d;transform:rotate(45deg);border-style:dashed}.state-symbol.unknown{color:#b53a21;background:linear-gradient(135deg,transparent 43%,#b53a21 44%,#b53a21 56%,transparent 57%)}.state-symbol.design{color:#2a5f93;border-radius:50%;box-shadow:inset 0 0 0 3px white}.state-symbol.takeover{color:#b53a21;border-radius:35%;position:relative}.state-symbol.takeover:after{content:'H';font-size:.62rem;font-weight:900}.state-symbol.stop{color:#162126;position:relative;background:#162126}.state-symbol.stop:after{content:'×';color:white;font-size:1rem;line-height:1}
@media(max-width:720px){main{min-width:0;overflow-x:clip}.phase4-guide{padding:1rem}.phase4-guide nav a{width:100%}.document-title{font-size:1.2rem}}
.proposal-table[tabindex="0"]{scrollbar-gutter:auto}.proposal-table:focus-visible{outline-offset:-4px}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
</style>`;
}

function enhanceReport(target, lang, registry) {
  let html = stripMarked(readText(target), "PHASE4_REPORT_GUIDE");
  html = html.replace(/<style id="phase4-report-style">[\s\S]*?<\/style>/g, "");
  html = html.replace(/<a class="phase4-skip"[\s\S]*?<\/a>/g, "");
  html = html.replace(/\n{2,}/g, "\n");
  if (!html.includes("../visual/assets/font-subset.css")) html = html.replace("</head>", `${reportPhase4Css()}\n</head>`);
  else html = html.replace("</head>", `${reportPhase4Css()}\n</head>`);
  html = html.replace("<body>", `<body>\n<a class="phase4-skip" href="#content">${lang === "zh" ? "跳至主要内容" : "Skip to main content"}</a>`);
  html = html.replace(/<main(?: id="content" tabindex="-1")?>/, '<main id="content" tabindex="-1">');
  html = html.replace(/<p class="translation-link"><a href="([^"]+)">/, `<p class="translation-link"><a href="$1" lang="${lang === "zh" ? "en" : "zh-CN"}" hreflang="${lang === "zh" ? "en" : "zh-CN"}">`);
  let h1 = 0;
  html = html.replace(/<h1>([\s\S]*?)<\/h1>/g, (match, inner) => {
    h1 += 1;
    return h1 === 2 ? `<p class="document-title" role="doc-subtitle">${inner}</p>` : match;
  });
  let h2 = 0;
  html = html.replace(/<h2(?![^>]*\bid=)([^>]*)>/g, (_, attrs) => `<h2${attrs} id="chapter-${++h2}">`);
  let tableIndex = 0;
  html = html.replace(/<div class="proposal-table">/g, () => {
    tableIndex += 1;
    const label = lang === "zh" ? `表格 T0${tableIndex}，可横向滚动` : `Table T0${tableIndex}, horizontally scrollable`;
    return `<div class="proposal-table" role="region" tabindex="0" aria-label="${label}">`;
  });
  html = html.replace(/<a class="figure-open"[^>]*>(<img[^>]+>)<\/a>/g, "$1");
  html = html.replace(/<button class="figure-open"[^>]*>(<img[^>]+>)<\/button>/g, "$1");
  html = html.replace(/<details class="figure-details">\s*<summary>(<img[^>]+>)<span>[\s\S]*?<\/span><\/summary>[\s\S]*?<\/details>/g, "$1");
  html = html.replace(/<figure class="proposal-figure"(?: id="[^"]+")?>\s*<img src="([^"]+)" alt="([^"]*F(\d\d)[^"]*)">/g, (_, src, alt, number) => {
    const id = `figure-f${number}`;
    const item = figureById(registry, `F${number}`);
    const title = languageValue(item, "title", lang);
    const summary = languageValue(item, "judgment", lang);
    const registryAlt = languageValue(item, "alt", lang);
    const label = lang === "zh" ? `放大 F${number} 原图并查看语义摘要` : `Enlarge original F${number} and read its semantic summary`;
    const close = lang === "zh" ? "再次激活此摘要可关闭；展开区为可横向滚动的 200% 原图。" : "Activate this summary again to close; the expanded region is a horizontally scrollable 200% original.";
    return `<figure class="proposal-figure" id="${id}"><details class="figure-details"><summary><img src="${src}" alt="${esc(registryAlt)}"><span>${label}</span></summary><div class="figure-details-panel"><div class="figure-details-viewport" tabindex="0" aria-label="${esc(`F${number} · ${title}`)}"><img src="${src}" alt="" aria-hidden="true"></div><p>${esc(summary)}</p><p>${close}</p></div></details>`;
  });
  for (const item of registry.figures) {
    const title = languageValue(item, "title", lang);
    const summary = languageValue(item, "judgment", lang);
    const figureId = `figure-${item.id.toLowerCase()}`;
    const figurePattern = new RegExp(`(<figure class="proposal-figure" id="${figureId}">[\\s\\S]*?<figcaption>)[\\s\\S]*?(</figcaption>)`);
    html = html.replace(figurePattern, `$1<strong>${item.id} · ${esc(title)}</strong><span>${esc(summary)}</span>$2`);
  }
  const guide = `<!-- PHASE4_REPORT_GUIDE_START -->
<section class="phase4-guide" aria-labelledby="phase4-guide-title">
  <h2 id="phase4-guide-title">${lang === "zh" ? "评审路径与统一图例" : "Review routes and unified legend"}</h2>
  <p><strong>京张在场 / Jing-Zhang In Situ</strong> · ${lang === "zh" ? "同一 canonical 项目名，双语并列。" : "One canonical project name, locked bilingually."}</p>
  <p><strong>${lang === "zh" ? "30 秒" : "30 seconds"}</strong> · ${lang === "zh" ? "项目名 → 三重在场 → 三原型 → AI 权限 → Human Takeover / 撤场" : "project → three kinds of presence → three prototypes → AI authority → Human Takeover / removal"}</p>
  <p class="r3-site-chain"><strong>${lang === "zh" ? "场地化唯一首用" : "Site-grounded sole first use"}</strong> · ${lang === "zh" ? "京张铁路遗址公园线索串联真实道路、公园与地标；大钟寺站城到达和文化/商业界面形成 CX10 候选冲突，因此仅测试 SC10 + IM06 only。Human Takeover 必须可见，Gate 未证即不开。" : "The Jing-Zhang rail / heritage-park trace links real roads, parks, and landmarks. Dazhongsi station arrival and its heritage/retail edge create the candidate CX10 conflict, so test SC10 + IM06 only. Human Takeover must stay visible; no evidenced Gate, no opening."}</p>
  <p><small>${lang === "zh" ? "© OpenStreetMap 贡献者 · ODbL 1.0 · 开放资料推导背景；非测绘/法定控制/道路红线。" : "© OpenStreetMap contributors · ODbL 1.0 · open-data-derived context; not survey/statutory/road redline."}</small></p>
  <nav aria-label="${lang === "zh" ? "30 秒与 3 分钟评审路径" : "30-second and 3-minute review routes"}"><a href="#figure-f01">F01 · SPACE</a><a href="#figure-f03">F03 · 3 PROTOTYPES</a><a href="#figure-f08">F08 · AUTHORITY</a><a href="#figure-f11">F11 · EXIT</a><a href="#phase4-boundaries">${lang === "zh" ? "限制" : "LIMITS"}</a></nav>
  ${legendHtml(lang, true)}
</section>
<!-- PHASE4_REPORT_GUIDE_END -->`;
  html = html.replace("</section>\n", `</section>\n${guide}\n`, 1);
  const boundary = `<!-- PHASE4_REPORT_GUIDE_START -->
<section class="phase4-boundaries" id="phase4-boundaries" aria-labelledby="phase4-boundary-title">
  <h2 id="phase4-boundary-title">${lang === "zh" ? "仍未完成或未获授权" : "Still incomplete or unauthorized"}</h2>
  <p>${lang === "zh" ? "六项未知指标：容积率、建筑高度、道路面积、人流、无障碍通过率、文保控制面积；三处重点区仍为 provisional；12 个场景的 controller 仍 unknown。" : "Six metrics remain unknown: floor area ratio, building height, road area, footfall, accessible pass rate, and heritage-control area. All three key areas remain provisional, and the controller for all twelve scenarios remains unknown."}</p>
  <p>${lang === "zh" ? "法律审查、无障碍审计、安全认证、现场调查、运营主体确认与正式批准均未完成或未获授权。" : "Legal review, accessibility audit, safety certification, site survey, operator appointment, and official approval remain incomplete or unauthorized."}</p>
</section>
<!-- PHASE4_REPORT_GUIDE_END -->`;
  html = html.replace("</main>", `${boundary}\n</main>`);
  writeText(target, html);
}

function visualPhase4Css() {
  return `
/* PHASE4_VISUAL_START */
  :root{--orange:#b53a21;--muted:#596260}body{font-synthesis:none}b,strong,h1,h2,h3,h4,.mast,.status,.metric b,.toolbar a,.toolbar button,.zoom-trigger{font-weight:700!important}.r3-site-chain{padding:.8rem 1rem;border:3px solid var(--orange);background:#fff5e8}
.phase4-guide{grid-column:1/-1;margin:0 0 1.5rem;padding:1.2rem 1.35rem;background:var(--paper);border:2px solid var(--ink);border-left:8px solid var(--orange)}.phase4-guide h2{margin:.1rem 0 .7rem}.phase4-guide p{max-width:88ch}.phase4-route{display:flex;flex-wrap:wrap;gap:.55rem}.phase4-route a{padding:.5rem .72rem;border:2px solid var(--ink);color:var(--ink);background:white;font-weight:800;text-decoration:none}.phase4-route a:focus-visible,.zoom-trigger:focus-visible,.lightbox button:focus-visible,.lightbox-viewport:focus-visible{outline:5px solid var(--focus);outline-offset:4px}.state-legend{display:flex;flex-wrap:wrap;gap:.6rem 1rem;margin:1rem 0 0;padding:0;list-style:none}.state-legend li{display:flex;align-items:center;gap:.42rem;font-weight:750}.state-symbol{display:inline-grid;width:1.15rem;height:1.15rem;place-items:center;border:3px solid currentColor}.state-symbol.known{color:#2d7980;border-radius:50%;background:#2d7980}.state-symbol.provisional{color:#b8893d;transform:rotate(45deg);border-style:dashed}.state-symbol.unknown{color:#b53a21;background:linear-gradient(135deg,transparent 43%,#b53a21 44%,#b53a21 56%,transparent 57%)}.state-symbol.design{color:#2a5f93;border-radius:50%;box-shadow:inset 0 0 0 3px white}.state-symbol.takeover{color:#b53a21;border-radius:35%;position:relative}.state-symbol.takeover:after{content:'H';font-size:.62rem;font-weight:900}.state-symbol.stop{color:#162126;background:#162126;position:relative}.state-symbol.stop:after{content:'×';color:white;font-size:1rem;line-height:1}.phase4-residuals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem;margin-top:1rem}.phase4-residuals article{padding:.9rem 1rem;background:#f7f2e8;border-top:4px solid var(--orange)}.phase4-residuals h3{margin:.1rem 0 .4rem;font-size:1rem}.zoom-trigger{display:block;width:calc(100% - 2rem);margin:.7rem 1rem 1rem;padding:.62rem;border:2px solid var(--ink);background:white;color:var(--ink);font:inherit;font-weight:800;cursor:pointer}.protocol-original-static img{display:block;width:100%}.lightbox{width:min(96vw,1500px);max-height:94vh;padding:0;border:4px solid var(--ink);background:var(--paper);color:var(--ink)}.lightbox::backdrop{background:rgba(10,20,23,.82)}.lightbox-bar{display:flex;justify-content:space-between;gap:1rem;align-items:center;padding:.7rem 1rem;background:var(--ink);color:white}.lightbox-bar p{margin:0;font-weight:800}.lightbox-bar button{padding:.45rem .8rem;border:2px solid white;background:transparent;color:white;font:inherit;font-weight:800}.lightbox-tools{display:flex;gap:.4rem;align-items:center}.lightbox-viewport{width:100%;height:78vh;overflow:auto;overscroll-behavior:contain;background:#e8e3d8}.lightbox-viewport img{display:block;width:100%;max-width:none;height:auto;margin:0}.lightbox .semantic-summary{padding:.7rem 1rem;margin:0;background:#f7f2e8}.dialog-open{overflow:hidden}.board{scroll-margin-top:1rem}@media(max-width:720px){.phase4-guide{padding:1rem}.phase4-route a{width:100%}.phase4-residuals{grid-template-columns:1fr}.lightbox{width:98vw}.lightbox-bar{align-items:flex-start;flex-direction:column}.lightbox-tools{flex-wrap:wrap}.lightbox-viewport{height:68vh}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*{animation:none!important;transition:none!important}}
/* PHASE4_VISUAL_END */
`;
}

function visualScript() {
  return `(()=>{
const drawer=document.querySelector('[data-drawer]');const open=document.querySelector('[data-open]');const close=document.querySelector('[data-close]');let previous=null;
const focusable=root=>[...root.querySelectorAll('a[href],button:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>!el.hidden);
const drawerPeers=()=>[...document.body.children].filter(el=>el!==drawer);
function showDrawer(){previous=document.activeElement;drawer.hidden=false;drawerPeers().forEach(el=>{el.inert=true});document.body.classList.add('dialog-open');close.focus()}
function hideDrawer(){drawer.hidden=true;drawerPeers().forEach(el=>{el.inert=false});document.body.classList.remove('dialog-open');previous?.focus()}
open?.addEventListener('click',showDrawer);close?.addEventListener('click',hideDrawer);
drawer?.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();hideDrawer()}if(event.key==='Tab'){const items=focusable(drawer);if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
const lightbox=document.querySelector('[data-lightbox]');const lightboxImage=lightbox?.querySelector('img');const lightboxTitle=lightbox?.querySelector('[data-lightbox-title]');const lightboxSummary=lightbox?.querySelector('[data-lightbox-summary]');const lightboxClose=lightbox?.querySelector('[data-lightbox-close]');const lightboxViewport=lightbox?.querySelector('.lightbox-viewport');let lightboxReturn=null;
function setZoom(value){if(!lightboxImage)return;lightboxImage.style.width=value+'%';lightboxViewport?.scrollTo({left:0,top:0,behavior:'auto'})}
document.querySelectorAll('[data-zoom-src]').forEach(button=>button.addEventListener('click',()=>{lightboxReturn=button;lightboxImage.src=button.dataset.zoomSrc;lightboxImage.alt=button.dataset.zoomAlt;lightboxTitle.textContent=button.dataset.zoomTitle;lightboxSummary.textContent=button.dataset.zoomSummary;setZoom(100);lightbox.showModal();lightboxClose.focus()}));
lightbox?.querySelectorAll('[data-lightbox-zoom]').forEach(button=>button.addEventListener('click',()=>setZoom(Number(button.dataset.lightboxZoom))));
lightbox?.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const items=focusable(lightbox);if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
lightboxClose?.addEventListener('click',()=>lightbox.close());lightbox?.addEventListener('cancel',event=>{event.preventDefault();lightbox.close()});lightbox?.addEventListener('click',event=>{if(event.target===lightbox)lightbox.close()});lightbox?.addEventListener('close',()=>{lightboxImage.removeAttribute('src');lightboxReturn?.focus()});
})();
`;
}

function addZoomButtons(html, lang, registry) {
  for (const item of registry.figures) {
    const token = `<figure class="board" id="${item.slug}">`;
    const start = html.indexOf(token);
    if (start < 0) throw new Error(`Visual missing ${item.id} (${item.slug})`);
    const end = html.indexOf("</figure>", start);
    if (end < 0) throw new Error(`Visual figure not closed: ${item.id}`);
    const title = languageValue(item, "title", lang);
    const alt = languageValue(item, "alt", lang);
    const summary = languageValue(item, "judgment", lang);
    const src = `../${item.paths[lang]}`;
    const label = lang === "zh" ? `放大 ${item.id} 原图并查看语义摘要` : `Enlarge original ${item.id} and read its semantic summary`;
    const button = `<button class="zoom-trigger" type="button" data-zoom-src="${esc(src)}" data-zoom-alt="${esc(alt)}" data-zoom-title="${esc(`${item.id} · ${title}`)}" data-zoom-summary="${esc(summary)}">${esc(label)}</button>`;
    let figure = html.slice(start, end);
    figure = figure.replace(/<a class="protocol-original"[^>]*>(<img[\s\S]*?)<span>[\s\S]*?<\/span><\/a>/, '<div class="protocol-original-static">$1</div>');
    figure = figure.replace(/(<img\s+src="[^"]+"\s+alt=")[^"]*(")/, `$1${esc(alt)}$2`);
    figure = figure.replace(/<figcaption><b>[\s\S]*?<\/b><span>[\s\S]*?<\/span><\/figcaption>/, `<figcaption><b>${item.id} · ${esc(title)}</b><span>${esc(summary)}</span></figcaption>`);
    if (!figure.includes("data-zoom-src")) figure += button;
    html = `${html.slice(0, start)}${figure}${html.slice(end)}`;
  }
  return html;
}

