async function generateCover(browser, fontCss) {
  fs.mkdirSync(MEDIA, { recursive: true });
  const page = await browser.newPage({ viewport: { width: 1600, height: 900 }, deviceScaleFactor: 1 });
  await page.setContent(coverHtml(fontCss), { waitUntil: "load" });
  await page.screenshot({ path: path.join(MEDIA, "cover.webp"), type: "webp", quality: 90 });
  await page.close();
}

