function normalizeLocalFontWeights() {
  const target = path.join(ASSETS, "font-subset.css");
  const original = readText(target);
  const normalized = original
    .replaceAll("font-weight:100 900;", "font-weight:400;")
    .replaceAll("font-weight:400 699;", "font-weight:400;")
    .replaceAll("font-weight:700 900;", "font-weight:700;");
  if (!normalized.includes("font-weight:400;") || !normalized.includes("font-weight:700;")) {
    throw new Error("Local Noto Sans SC regular and bold faces were not established");
  }
  if (normalized !== original) fs.writeFileSync(target, normalized, "utf8");
  return normalized;
}

