async function renderPdf(browser, html, target) {
  const page = await browser.newPage();
  await page.emulateMedia({ media: "print", reducedMotion: "reduce" });
  await page.setContent(html, { waitUntil: "load", timeout: 120000 });
  await page.evaluate(() => document.fonts.ready);
  const layoutAssertion = await page.evaluate(() => {
    const intersects = (first, second) => first.left < second.right && first.right > second.left && first.top < second.bottom && first.bottom > second.top;
    return [...document.querySelectorAll(".native-protocol")].map((figure) => {
      const figureBox = figure.getBoundingClientRect();
      const leafSizes = [...figure.querySelectorAll("strong,span,h3,dt,dd,b,p")]
        .filter((element) => element.children.length === 0 && element.textContent.trim() && element.getBoundingClientRect().width > 0 && element.getBoundingClientRect().height > 0)
        .map((element) => Number.parseFloat(getComputedStyle(element).fontSize) * 0.75);
      const overflow = [...figure.querySelectorAll(".scenario-card,.red-result,.governance-cards article,.prohibited-band")]
        .filter((element) => element.scrollHeight - element.clientHeight > 1 || element.scrollWidth - element.clientWidth > 1)
        .map((element) => ({
          id: element.getAttribute("data-scenario") || element.getAttribute("data-test") || element.className,
          height_overflow_px: element.scrollHeight - element.clientHeight,
          width_overflow_px: element.scrollWidth - element.clientWidth,
        }));
      const summaryBands = [...figure.closest(".page").querySelectorAll(":scope > .direct-band")];
      return {
        figure: figure.getAttribute("data-figure"),
        scenarios: figure.querySelectorAll("[data-scenario]").length,
        red_results: figure.querySelectorAll("[data-test]").length,
        prohibited_visible: Boolean(figure.querySelector(".prohibited-band")?.getBoundingClientRect().height),
        minimum_selectable_text_pt: leafSizes.length ? Math.min(...leafSizes) : 0,
        overflow,
        summary_band_count: summaryBands.length,
        summary_band_intersections: summaryBands.filter((band) => intersects(figureBox, band.getBoundingClientRect())).length,
      };
    });
  });
  const headerAssertions = await page.evaluate(() => [...document.querySelectorAll(".a3-page .page-header")].map((header) => {
    const box = header.getBoundingClientRect();
    const border = Number.parseFloat(getComputedStyle(header).borderBottomWidth) || 0;
    const separatorTop = box.bottom - border;
    const title = header.querySelector("h2").getBoundingClientRect();
    const judgment = header.querySelector(":scope > p").getBoundingClientRect();
    const pageLabel = header.closest(".page").getAttribute("aria-label");
    const record = (name, value) => ({
      name,
      bbox_css_px: [value.left, value.top, value.right, value.bottom],
      gap_to_separator_css_px: separatorTop - value.bottom,
      intersects_separator: value.bottom > separatorTop + 0.01,
    });
    const text = [record("title", title), record("judgment", judgment)];
    return {
      page: pageLabel,
      separator_bbox_css_px: [box.left, separatorTop, box.right, box.bottom],
      text,
      intersections: text.filter((item) => item.intersects_separator).length,
    };
  }));
  const expectedOutlineTitles = await page.evaluate(() => [...document.querySelectorAll("h1,h2,h3")]
    .filter((heading) => heading.getClientRects().length)
    .map((heading) => heading.textContent.replace(/\s+/g, " ").trim()));
  const baseName = path.basename(target);
  const requiredOutlineCount = EXPECTED_ENGLISH_OUTLINE_COUNTS[baseName];
  if (requiredOutlineCount !== undefined && expectedOutlineTitles.length !== requiredOutlineCount) {
    throw new Error(`English outline DOM count ${expectedOutlineTitles.length}, expected ${requiredOutlineCount} for ${baseName}`);
  }
  if (!expectedOutlineTitles.every((title) => normalizeOutlineWhitespace(normalizeOutlineWhitespace(title)) === normalizeOutlineWhitespace(title))) {
    throw new Error(`Outline whitespace normalization is not idempotent for ${baseName}`);
  }
  PDF_OUTLINE_ASSERTIONS[baseName] = {
    expected_count: expectedOutlineTitles.length,
    expected_titles: expectedOutlineTitles.map(normalizeOutlineWhitespace),
    normalization: "replace every newline or contiguous whitespace run with one U+0020, then trim",
    normalization_idempotent: true,
  };
  PDF_HEADER_ASSERTIONS[path.basename(target)] = headerAssertions;
  const layoutFailures = layoutAssertion.filter((item) => item.overflow.length || item.summary_band_intersections || item.minimum_selectable_text_pt + 0.01 < (item.figure && target.includes("a0-") ? 18 : 9) || (item.figure === "F08" && item.scenarios !== 12) || (item.figure === "F11" && (item.red_results < 4 || !item.prohibited_visible)));
  if (layoutFailures.length) throw new Error(`Native protocol layout assertion failed for ${path.basename(target)}: ${JSON.stringify(layoutFailures)}`);
  const headerFailures = target.endsWith("a3-booklet.en.pdf") ? headerAssertions.filter((item) => item.intersections) : [];
  if (headerFailures.length) throw new Error(`English A3 header separator bbox assertion failed for ${path.basename(target)}: ${JSON.stringify(headerFailures)}`);
  await page.pdf({
    path: target,
    printBackground: true,
    preferCSSPageSize: true,
    tagged: true,
    outline: true,
    displayHeaderFooter: false,
  });
  await page.close();
  return layoutAssertion;
}

function addCompatibleRoleMap(target, expectedTitles) {
  const script = String.raw`
import json
import os
import re
import sys
from pypdf import PdfReader, PdfWriter
from pypdf.generic import DictionaryObject, NameObject, TextStringObject

source = sys.argv[1]
expected = [re.sub(r"\s+", " ", value).strip() for value in json.loads(sys.argv[2])]
temporary = source + ".rolemap.tmp"
reader = PdfReader(source)
writer = PdfWriter()
writer.clone_document_from_reader(reader)
writer.pdf_header = "%PDF-1.4"
struct_ref = writer._root_object.get("/StructTreeRoot")
if struct_ref is None:
    raise RuntimeError("StructTreeRoot missing")
struct = struct_ref.get_object()
role_ref = struct.get("/RoleMap")
role_map = role_ref.get_object() if role_ref is not None else DictionaryObject()
role_map[NameObject("/Strong")] = NameObject("/Span")
struct[NameObject("/RoleMap")] = role_map

def walk_outline_nodes(container):
    current_ref = container.get("/First")
    while current_ref is not None:
        current = current_ref.get_object()
        yield current
        yield from walk_outline_nodes(current)
        current_ref = current.get("/Next")

outlines_ref = writer._root_object.get("/Outlines")
if outlines_ref is None:
    raise RuntimeError("PDF outline root missing")
nodes = list(walk_outline_nodes(outlines_ref.get_object()))
before = [str(node.get("/Title", "")) for node in nodes]
if len(nodes) != len(expected):
    raise RuntimeError(f"PDF outline node count {len(nodes)}, expected {len(expected)}")
changed = []
for index, (node, current, wanted) in enumerate(zip(nodes, before, expected, strict=True), start=1):
    if re.sub(r"\s+", "", current) != re.sub(r"\s+", "", wanted):
        raise RuntimeError(f"PDF outline semantic mismatch at {index}: {current!r} != {wanted!r}")
    if current != wanted:
        changed.append({"index": index, "before": current, "after": wanted})
    node[NameObject("/Title")] = TextStringObject(wanted)

metadata = {str(key): str(value) for key, value in (reader.metadata or {}).items() if value is not None}
metadata["/CreationDate"] = "D:20260828000000+08'00'"
metadata["/ModDate"] = "D:20260828000000+08'00'"
writer.add_metadata(metadata)
with open(temporary, "wb") as handle:
    writer.write(handle)
reopened = PdfReader(temporary)

def flatten(items):
    values = []
    for item in items:
        if isinstance(item, list):
            values.extend(flatten(item))
        else:
            values.append(str(getattr(item, "title", item)))
    return values

after = flatten(reopened.outline)
if after != expected:
    raise RuntimeError(f"Normalized PDF outline differs after reopen: {after!r} != {expected!r}")
if any(re.sub(r"\s+", " ", value).strip() != value for value in after):
    raise RuntimeError("Normalized PDF outline contains non-canonical whitespace")
if any(re.sub(r"\s+", " ", re.sub(r"\s+", " ", value).strip()).strip() != value for value in after):
    raise RuntimeError("PDF outline whitespace normalization is not idempotent")
os.replace(temporary, source)
print(json.dumps({"before": before, "after": after, "changed": changed, "normalization_idempotent": True}, ensure_ascii=False))
`;
  const result = spawnSync(process.env.PHASE4_PYTHON || "python", ["-c", script, target, JSON.stringify(expectedTitles)], {
    encoding: "utf8",
    env: { ...process.env, PYTHONIOENCODING: "utf-8" },
  });
  if (result.status !== 0) throw new Error(`RoleMap normalization failed for ${path.basename(target)}: ${result.stderr || result.stdout}`);
  return JSON.parse(result.stdout.trim());
}

function assertPdfOutline(target, expectedTitles, negativeFixture = false) {
  const script = String.raw`
import json
import re
import sys
from pypdf import PdfReader

source = sys.argv[1]
expected = json.loads(sys.argv[2])
forbidden = json.loads(sys.argv[3])
negative = sys.argv[4] == "1"

def flatten(items):
    values = []
    for item in items:
        if isinstance(item, list):
            values.extend(flatten(item))
        else:
            values.append(str(getattr(item, "title", item)))
    return values

actual = flatten(PdfReader(source).outline)
if negative:
    for index, title in enumerate(actual):
        if "Zero Overlaps" in title:
            actual[index] = title.replace("Zero Overlaps", "ZeroOverlaps")
            break
if actual != expected:
    raise RuntimeError(f"PDF outline title assertion failed: actual={actual!r}, expected={expected!r}")
glued = sorted({token for token in forbidden for title in actual if token in title})
if glued:
    raise RuntimeError(f"Forbidden glued PDF outline tokens: {glued}")
canonical = [re.sub(r"\s+", " ", title).strip() for title in actual]
if canonical != actual or [re.sub(r"\s+", " ", title).strip() for title in canonical] != canonical:
    raise RuntimeError("PDF outline whitespace normalization is not canonical and idempotent")
print(json.dumps({"count": len(actual), "titles": actual, "forbidden_glue": glued, "normalization_idempotent": True}, ensure_ascii=False))
`;
  const result = spawnSync(process.env.PHASE4_PYTHON || "python", [
    "-c",
    script,
    target,
    JSON.stringify(expectedTitles),
    JSON.stringify(FORBIDDEN_ENGLISH_OUTLINE_GLUE),
    negativeFixture ? "1" : "0",
  ], {
    encoding: "utf8",
    env: { ...process.env, PYTHONIOENCODING: "utf-8" },
  });
  if (result.status !== 0) throw new Error(`PDF outline assertion failed for ${path.basename(target)}: ${result.stderr || result.stdout}`);
  return JSON.parse(result.stdout.trim());
}

