    output_sha256: Object.fromEntries(OUTPUTS.map((relative) => [relative, sha256(path.join(SUB, relative))])),
    outputs: layout.outputs,
    restrictions: layout.residual_boundaries,
  };
  writeTextAtomic(CONTRACT_PATH, `${JSON.stringify(contract, null, 2)}\n`);
  console.log(JSON.stringify({ ok: true, outputs: OUTPUTS.length, page_contract: contract.page_contract, toolchain: contract.toolchain }, null, 2));
}

function check() {
  assertFrozen();
  const contract = readJson(CONTRACT_PATH);
  const failures = [];
  for (const [relative, expected] of Object.entries(contract.output_sha256)) {
    const target = path.join(SUB, relative);
    const actual = fs.existsSync(target) ? sha256(target) : "missing";
    if (actual !== expected) failures.push(`${relative}: ${actual}`);
  }
  let negativeApplied = false;
  for (const [baseName, requiredCount] of Object.entries(EXPECTED_ENGLISH_OUTLINE_COUNTS)) {
    const assertion = contract.pdf_outline_assertions?.[baseName];
    if (!assertion || assertion.expected_count !== requiredCount || assertion.expected_titles.length !== requiredCount) {
      failures.push(`${baseName}: missing exact ${requiredCount}-node outline contract`);
      continue;
    }
    try {
      const result = assertPdfOutline(
        path.join(DRAWINGS, baseName),
        assertion.expected_titles,
        NEGATIVE_OUTLINE_GLUE && !negativeApplied,
      );
      negativeApplied ||= NEGATIVE_OUTLINE_GLUE;
      if (result.count !== requiredCount || !result.normalization_idempotent) failures.push(`${baseName}: outline assertion result drift`);
    } catch (error) {
      failures.push(String(error.message || error));
    }
  }
  if (failures.length) throw new Error(`Phase 4 output drift:\n${failures.join("\n")}`);
  console.log(JSON.stringify({ ok: true, outputs: Object.keys(contract.output_sha256).length, frozen_inputs: true, english_outline_nodes: { a3: 29, a0: 22 } }, null, 2));
}

if (process.argv.includes("--check") || NEGATIVE_OUTLINE_GLUE) check();
else await generate();
